import React from "react"
import styled from "styled-components"

import { Link } from "gatsby"

const TagListWrapper = styled.div`
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
  margin-bottom: 16px;
`

const TagItem = styled.div`
  display: inline-flex;
  align-items: center;
  padding: 6px 12px;
  background: ${props => 
    props.selected 
      ? props.theme?.colors?.selectedTagBackground || '#2563eb'
      : props.theme?.colors?.tagBackground || '#f3f4f6'};
  color: ${props => 
    props.selected 
      ? props.theme?.colors?.selectedTagText || '#ffffff'
      : props.theme?.colors?.tagText || '#2a2a2a'};
  border: 1px solid ${props => props.theme?.colors?.border || '#e5e7eb'};
  border-radius: 16px;
  font-size: 13px;
  font-weight: 500;
  text-decoration: none;
  transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
  position: relative;
  overflow: hidden;
  letter-spacing: 0.3px;
  cursor: pointer;

  &::before {
    content: '#';
    margin-right: 4px;
    color: ${props => props.selected ? '#ffffff' : '#2563eb'};
    font-weight: 600;
  }

  &::after {
    content: '';
    position: absolute;
    top: 0;
    left: -100%;
    width: 100%;
    height: 100%;
    background: linear-gradient(135deg, #2563eb 0%, #7c3aed 100%);
    transition: left 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    z-index: -1;
  }

  &:hover {
    color: #ffffff;
    border-color: #2563eb;
    transform: translateY(-2px);
    box-shadow: 0 4px 12px rgba(37, 99, 235, 0.3);
  }

  &:hover::after {
    left: 0;
  }

  &:hover::before {
    color: #ffffff;
  }

  @media (max-width: 768px) {
    font-size: 12px;
    padding: 4px 8px;
  }
`

const TagLink = styled(Link)`
  display: inline-flex;
  align-items: center;
  padding: 6px 12px;
  background: ${props => 
    props.selected 
      ? props.theme?.colors?.selectedTagBackground || '#2563eb'
      : props.theme?.colors?.tagBackground || '#f3f4f6'};
  color: ${props => 
    props.selected 
      ? props.theme?.colors?.selectedTagText || '#ffffff'
      : props.theme?.colors?.tagText || '#2a2a2a'};
  border: 1px solid ${props => props.theme?.colors?.border || '#e5e7eb'};
  border-radius: 16px;
  font-size: 13px;
  font-weight: 500;
  text-decoration: none;
  transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
  position: relative;
  overflow: hidden;
  letter-spacing: 0.3px;

  &::before {
    content: '#';
    margin-right: 4px;
    color: ${props => props.selected ? '#ffffff' : '#2563eb'};
    font-weight: 600;
  }

  &::after {
    content: '';
    position: absolute;
    top: 0;
    left: -100%;
    width: 100%;
    height: 100%;
    background: linear-gradient(135deg, #2563eb 0%, #7c3aed 100%);
    transition: left 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    z-index: -1;
  }

  &:hover {
    color: #ffffff;
    border-color: #2563eb;
    transform: translateY(-2px);
    box-shadow: 0 4px 12px rgba(37, 99, 235, 0.3);
  }

  &:hover::after {
    left: 0;
  }

  &:hover::before {
    color: #ffffff;
  }

  @media (max-width: 768px) {
    font-size: 12px;
    padding: 4px 8px;
  }
`

const TagCount = styled.span`
  margin-left: 4px;
  padding: 2px 6px;
  background: ${props => props.selected ? '#ffffff' : '#2563eb'};
  color: ${props => props.selected ? '#2563eb' : '#ffffff'};
  border-radius: 10px;
  font-size: 10px;
  font-weight: 600;
  min-width: 16px;
  text-align: center;
  
  @media (max-width: 768px) {
    font-size: 9px;
    padding: 1px 4px;
  }
`

const spaceToDash = text => {
  return text.replace(/\s+/g, "-")
}

const TagList = React.memo(({ tagList, count, selected, onClick, showCount = false, tagCount = {} }) => {
  if (!tagList || tagList.length === 0) return null

  // 기존 방식 (count가 있는 경우) - tags 페이지에서 사용
  if (count) {
    return (
      <TagListWrapper>
        {tagList.map((tag, i) => (
          <TagItem
            key={`${tag.fieldValue}-${i}`}
            selected={tag.fieldValue === selected}
            onClick={() => onClick && onClick(tag.fieldValue)}
          >
            {spaceToDash(tag.fieldValue)}
            <TagCount selected={tag.fieldValue === selected}>
              {tag.totalCount}
            </TagCount>
          </TagItem>
        ))}
      </TagListWrapper>
    )
  }

  // 새로운 방식 (간단한 태그 리스트) - 포스트에서 사용
  return (
    <TagListWrapper>
      {tagList.map((tag, i) => (
        <TagLink key={`${tag}-${i}`} to={`/tags?q=${encodeURIComponent(tag)}`}>
          {spaceToDash(tag)}
          {showCount && tagCount[tag] && (
            <TagCount>{tagCount[tag]}</TagCount>
          )}
        </TagLink>
      ))}
    </TagListWrapper>
  )
})

export default TagList
