import React from "react"
import { navigate } from "gatsby"
import styled from "styled-components"
import { BiLeftArrowAlt, BiRightArrowAlt } from "react-icons/bi"

import Divider from "components/Divider"
import Bio from "components/Bio"
import Comment from "./Comment"

const ArticleButtonContainer = styled.div`
  display: flex;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 48px;

  @media (max-width: 768px) {
    margin-bottom: 40px;
    padding: 0 16px;
    flex-direction: column;
    gap: 16px;
  }
`

const ArticleButtonWrapper = styled.div`
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: ${props => (props.right ? "flex-end" : "flex-start")};
  padding: 24px;
  max-width: 320px;
  min-height: 100px;
  background: ${props => props.theme?.name === 'dark' ? '#1a1a1a' : '#ffffff'};
  border: 1px solid ${props => props.theme?.name === 'dark' ? '#2a2a2a' : '#e5e7eb'};
  border-radius: 16px;
  box-shadow: 0 4px 16px ${props => props.theme?.name === 'dark' ? 'rgba(0, 0, 0, 0.2)' : 'rgba(37, 99, 235, 0.08)'};
  cursor: pointer;
  transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
  overflow: hidden;

  &::before {
    content: '';
    position: absolute;
    top: 0;
    left: ${props => (props.right ? '0' : 'auto')};
    right: ${props => (props.right ? 'auto' : '0')};
    width: 4px;
    height: 100%;
    background: linear-gradient(135deg, #2563eb 0%, #7c3aed 100%);
    transform: ${props => (props.right ? 'translateX(-100%)' : 'translateX(100%)')};
    transition: transform 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
  }

  &:hover {
    transform: translateY(-4px);
    box-shadow: 0 12px 32px ${props => props.theme?.name === 'dark' ? 'rgba(0, 0, 0, 0.3)' : 'rgba(37, 99, 235, 0.15)'};
    border-color: #2563eb;
  }

  &:hover::before {
    transform: translateX(0);
  }

  @media (max-width: 768px) {
    max-width: 100%;
    min-height: 80px;
    padding: 20px;
  }
`

const ArrowFlexWrapper = styled.div`
  width: 100%;
  display: flex;
  align-items: center;
  flex-direction: ${props => (props.right ? "row-reverse" : "row")};
  gap: 16px;
`

const ArticleButtonTextWrapper = styled.div`
  display: flex;
  flex-direction: column;
  align-items: ${props => (props.right ? "flex-end" : "flex-start")};
  flex: 1;
  min-width: 0;
`

const Arrow = styled.div`
  display: flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: ${props => props.theme?.name === 'dark' ? '#2a2a2a' : '#f3f4f6'};
  color: ${props => props.theme?.name === 'dark' ? '#3b82f6' : '#2563eb'};
  font-size: 20px;
  transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
  flex-shrink: 0;

  ${ArticleButtonWrapper}:hover & {
    background: linear-gradient(135deg, #2563eb 0%, #7c3aed 100%);
    color: #ffffff;
    transform: ${props => (props.right ? 'translateX(4px)' : 'translateX(-4px)')};
  }

  @media (max-width: 768px) {
    width: 36px;
    height: 36px;
    font-size: 18px;
  }
`

const ArticleButtonLabel = styled.div`
  margin-bottom: 8px;
  font-size: 13px;
  font-weight: 600;
  color: ${props => props.theme?.name === 'dark' ? '#9ca3af' : '#6b7280'};
  text-transform: uppercase;
  letter-spacing: 0.5px;
  text-align: ${props => (props.right ? "right" : "left")};

  @media (max-width: 768px) {
    font-size: 12px;
    margin-bottom: 6px;
  }
`

const ArticleButtonTitle = styled.div`
  font-size: 16px;
  font-weight: 600;
  line-height: 1.4;
  color: ${props => props.theme?.name === 'dark' ? '#ffffff' : '#0a0a0a'};
  text-align: ${props => (props.right ? "right" : "left")};
  text-overflow: ellipsis;
  overflow: hidden;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  
  ${ArticleButtonWrapper}:hover & {
    background: linear-gradient(135deg, #2563eb 0%, #7c3aed 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
  }

  @media (max-width: 768px) {
    font-size: 15px;
  }
`

const CommentWrapper = styled.div`
  @media (max-width: 768px) {
    padding: 0 15px;
  }
`

const ArticleButton = ({ right, children, onClick }) => {
  return (
    <ArticleButtonWrapper right={right} onClick={onClick}>
      <ArrowFlexWrapper right={right}>
        <Arrow right={right}>{right ? <BiRightArrowAlt /> : <BiLeftArrowAlt />}</Arrow>
        <ArticleButtonTextWrapper right={right}>
          <ArticleButtonLabel right={right}>
            {right ? "다음 포스트" : "이전 포스트"}
          </ArticleButtonLabel>
          <ArticleButtonTitle right={right}>{children}</ArticleButtonTitle>
        </ArticleButtonTextWrapper>
      </ArrowFlexWrapper>
    </ArticleButtonWrapper>
  )
}

const Footer = ({ previous, next }) => {
  return (
    <>
      <ArticleButtonContainer>
        {previous ? (
          <ArticleButton onClick={() => navigate(previous?.fields?.slug)}>
            {previous?.frontmatter?.title}
          </ArticleButton>
        ) : (
          <div></div>
        )}
        {next && (
          <ArticleButton right onClick={() => navigate(next?.fields?.slug)}>
            {next?.frontmatter?.title}
          </ArticleButton>
        )}
      </ArticleButtonContainer>

      <Bio />
      <CommentWrapper>
        <Divider mt="32px" />

        <Comment />
      </CommentWrapper>
    </>
  )
}

export default Footer
