import React from "react"
import styled from "styled-components"
import { navigate } from "gatsby"

import {
  FaGithub,
  FaKaggle,
  FaFacebook,
  FaTwitter,
  FaLinkedin,
  FaInstagram,
} from "react-icons/fa"

import {
  FaXTwitter,
  FaRegEnvelope,
  FaMedium,
  FaBlogger,
  FaRegFileLines,
  FaLink,
  FaUser,
} from "react-icons/fa6"

import { siteUrl, description, author, links } from "../../../blog-config"

const BioWrapper = styled.div`
  position: relative;
  display: flex;
  align-items: center;
  padding: 48px;
  margin: 32px 0;
  background: ${props => props.theme?.name === 'dark' ? '#1a1a1a' : '#f8fafc'};
  border-radius: 24px;
  border: 1px solid ${props => props.theme?.name === 'dark' ? '#2a2a2a' : '#e5e7eb'};
  box-shadow: 0 8px 32px ${props => props.theme?.name === 'dark' ? 'rgba(0, 0, 0, 0.3)' : 'rgba(37, 99, 235, 0.1)'};
  transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
  overflow: hidden;

  &::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 4px;
    background: linear-gradient(135deg, #2563eb 0%, #7c3aed 100%);
  }

  &:hover {
    transform: translateY(-4px);
    box-shadow: 0 16px 48px ${props => props.theme?.name === 'dark' ? 'rgba(0, 0, 0, 0.4)' : 'rgba(37, 99, 235, 0.15)'};
  }

  @media (max-width: 768px) {
    flex-direction: column;
    text-align: center;
    padding: 32px 20px;
    margin: 24px 16px;
  }
`

const profileImageRoot =
  typeof window !== "undefined" && window.location.host === "localhost:8000"
    ? "http://localhost:8000"
    : siteUrl

const ProfileContainer = styled.div`
  position: relative;
  flex: 0 0 auto;
  margin-right: 24px;
  cursor: pointer;

  @media (max-width: 768px) {
    margin-right: 0;
    margin-bottom: 24px;
  }
`

const Profile = styled.div`
  width: 120px;
  height: 120px;
  border-radius: 50%;
  background-image: url(${profileImageRoot}/profile.png);
  background-size: cover;
  background-position: center;
  border: 4px solid ${props => props.theme?.name === 'dark' ? '#2a2a2a' : '#e5e7eb'};
  box-shadow: 0 8px 24px ${props => props.theme?.name === 'dark' ? 'rgba(0, 0, 0, 0.3)' : 'rgba(37, 99, 235, 0.1)'};
  transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);

  &:hover {
    transform: scale(1.05);
    box-shadow: 0 12px 32px ${props => props.theme?.name === 'dark' ? 'rgba(0, 0, 0, 0.4)' : 'rgba(37, 99, 235, 0.15)'};
  }

  @media (max-width: 768px) {
    width: 100px;
    height: 100px;
  }
`

const ProfileGlow = styled.div`
  position: absolute;
  top: -4px;
  left: -4px;
  right: -4px;
  bottom: -4px;
  border-radius: 50%;
  background: linear-gradient(135deg, #2563eb 0%, #7c3aed 100%);
  opacity: 0;
  transition: opacity 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
  z-index: -1;

  ${ProfileContainer}:hover & {
    opacity: 0.3;
  }
`

const ClickHint = styled.div`
  position: absolute;
  bottom: -8px;
  left: 50%;
  transform: translateX(-50%);
  background: linear-gradient(135deg, #2563eb 0%, #7c3aed 100%);
  color: white;
  padding: 4px 8px;
  border-radius: 12px;
  font-size: 11px;
  font-weight: 600;
  opacity: 0;
  transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
  pointer-events: none;
  white-space: nowrap;

  ${ProfileContainer}:hover & {
    opacity: 1;
    transform: translateX(-50%) translateY(-4px);
  }

  &::before {
    content: '';
    position: absolute;
    top: -4px;
    left: 50%;
    transform: translateX(-50%);
    border-left: 4px solid transparent;
    border-right: 4px solid transparent;
    border-bottom: 4px solid #2563eb;
  }

  @media (max-width: 768px) {
    font-size: 10px;
    padding: 3px 6px;
  }
`

const InfoContainer = styled.div`
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: center;
`

const Author = styled.div`
  margin-bottom: 8px;
  font-size: 32px;
  font-weight: 800;
  color: ${props => props.theme?.name === 'dark' ? '#ffffff' : '#0a0a0a'};
  background: linear-gradient(135deg, #2563eb 0%, #7c3aed 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  letter-spacing: -0.5px;

  @media (max-width: 768px) {
    font-size: 28px;
  }
`

const Description = styled.div`
  margin-bottom: 24px;
  line-height: 1.6;
  font-size: 18px;
  color: ${props => props.theme?.name === 'dark' ? '#d1d5db' : '#374151'};
  font-weight: 400;

  @media (max-width: 768px) {
    font-size: 16px;
    margin-bottom: 20px;
  }
`

const LinksWrapper = styled.div`
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  
  @media (max-width: 768px) {
    justify-content: center;
  }
`

const LinkItem = styled.a`
  display: flex;
  align-items: center;
  justify-content: center;
  width: 48px;
  height: 48px;
  border-radius: 12px;
  background: ${props => props.theme?.name === 'dark' ? '#0a0a0a' : '#ffffff'};
  border: 2px solid ${props => props.theme?.name === 'dark' ? '#2a2a2a' : '#e5e7eb'};
  transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
  cursor: pointer;

  &:hover {
    background: linear-gradient(135deg, #2563eb 0%, #7c3aed 100%);
    border-color: #2563eb;
    transform: translateY(-2px) scale(1.05);
    box-shadow: 0 8px 24px rgba(37, 99, 235, 0.4);
  }

  &:hover svg path {
    fill: #ffffff;
  }

  & svg {
    width: 20px;
    height: 20px;
    transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
  }

  & svg path {
    fill: ${props => props.theme?.name === 'dark' ? '#ffffff' : '#6b7280'};
    transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
  }

  @media (max-width: 768px) {
    width: 44px;
    height: 44px;
    border-radius: 10px;
    
    & svg {
      width: 18px;
      height: 18px;
    }
  }
`



const Link = ({ link, children }) => {
  if (!link) return null
  return (
    <LinkItem href={link} target="_blank" rel="noreferrer">
      {children}
    </LinkItem>
  )
}

const Bio = () => {
  const {
    github,
    kaggle,
    instagram,
    facebook,
    twitter,
    x,
    blogger,
    medium,
    linkedIn,
    email,
    resume,
    link,
  } = links

  const handleProfileClick = () => {
    navigate('/about')
  }

  return (
      <BioWrapper id="bio">
        <ProfileContainer onClick={handleProfileClick}>
          <ProfileGlow />
          <Profile />
          <ClickHint>About Me</ClickHint>
        </ProfileContainer>
        <InfoContainer>
          <Author>@{author}</Author>
          <Description>{description}</Description>
          <LinksWrapper>
            <Link link={github}>
              <FaGithub />
            </Link>
            <Link link={kaggle}>
              <FaKaggle />
            </Link>
            <Link link={instagram}>
              <FaInstagram />
            </Link>
            <Link link={facebook}>
              <FaFacebook />
            </Link>
            <Link link={twitter}>
              <FaTwitter />
            </Link>
            <Link link={x}>
              <FaXTwitter />
            </Link>
            <Link link={medium}>
              <FaMedium />
            </Link>
            <Link link={blogger}>
              <FaBlogger />
            </Link>
            <Link link={linkedIn}>
              <FaLinkedin />
            </Link>
            <Link link={email}>
              <FaRegEnvelope />
            </Link>
            <Link link={resume}>
              <FaRegFileLines />
            </Link>
            <Link link={link}>
              <FaLink />
            </Link>
          </LinksWrapper>
        </InfoContainer>
    </BioWrapper>
  )
}

export default Bio
